import zipfile
import xml.etree.ElementTree as ET
import re

path = 'budget.xlsx'

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

with zipfile.ZipFile(path) as z:
    print("ZIP contents:", z.namelist())

    # workbook.xml -> sheet names + rIds
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("Sheets:", sheets)

    # workbook.xml.rels -> rId -> target
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {}
    for rel in rels:
        relmap[rel.get('Id')] = rel.get('Target')
    print("Rels:", relmap)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.find('m:sst', NS):
            txt = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(txt)
    print("Shared strings:", shared)

    def col_to_idx(ref):
        m = re.match(r'([A-Z]+)(\d+)', ref)
        col = 0
        for ch in m.group(1):
            col = col * 26 + (ord(ch) - 64)
        return col - 1, int(m.group(2)) - 1

    for name, rid in sheets:
        target = relmap[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        print(f"\n--- Sheet: {name} ---")
        root = ET.fromstring(z.read(target))
        rows = []
        for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            cells = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None:
                    val = v.text
                    if t == 's':
                        val = shared[int(val)]
                    elif t == 'b':
                        val = val == '1'
                    elif t == 'str' or t == 'inlineStr':
                        pass
                    elif t is None and val is not None:
                        try:
                            val = float(val)
                        except ValueError:
                            pass
                else:
                    isel = c.find('m:is', NS)
                    if isel is not None:
                        val = ''.join(t.text or '' for t in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                ci, ri = col_to_idx(ref)
                cells[ci] = val
            if cells:
                maxc = max(cells)
                rows.append([cells.get(i) for i in range(maxc + 1)])
        for i, r in enumerate(rows, 1):
            print(i, r)

