with zipfile.ZipFile('budget.xlsx') as z:
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(sh.get('name'), sh.get(f'{{{R}}}id')) for sh in wb.find(f'{{{M}}}sheets')]
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {rel.get('Id'): rel.get('Target') for rel in rels}
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.find(f'{{{M}}}sst'):
            shared.append(''.join(t.text or '' for t in si.iter(f'{{{M}}}t')))
    def ci(ref):
        col = 0
        for ch in re.match(r'[A-Z]+', ref).group(0):
            col = col * 26 + (ord(ch) - 64)
        return col - 1
    for name, rid in sheets:
        root = ET.fromstring(z.read(relmap[rid].lstrip('/')))
        rows = {}
        for row in root.iter(f'{{{M}}}row'):
            cells = {}
            for c in row.findall(f'{{{M}}}c'):
                v = c.find(f'{{{M}}}v')
                val = None
                if v is not None:
                    val = v.text
                    if c.get('t') == 's':
                        val = shared[int(val)]
                    elif c.get('t') is None and val is not None:
                        try: val = float(val)
                        except ValueError: pass
                else:
                    isel = c.find(f'{{{M}}}is')
                    if isel is not None:
                        val = ''.join(x.text or '' for x in isel.iter(f'{{{M}}}t'))
                cells[ci(c.get('r'))] = val
            if cells:
                rnum = int(re.search(r'\d+', row.get('r')).group(0))
                rows[rnum] = cells
        total = 0.0
        for rnum in sorted(rows):
            rowvals = [rows[rnum].get(i) for i in range(max(rows[rnum]) + 1)]
            nums = [v for v in rowvals if isinstance(v, (int, float))]
            total += sum(nums)
        print(name, round(total, 2))

import zipfile, re
import xml.etree.ElementTree as ET
M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
with zipfile.ZipFile('budget.xlsx') as z:
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(sh.get('name'), sh.get(f'{{{R}}}id')) for sh in wb.find(f'{{{M}}}sheets')]
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {rel.get('Id'): rel.get('Target') for rel in rels}
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.find(f'{{{M}}}sst'):
            shared.append(''.join(t.text or '' for t in si.iter(f'{{{M}}}t')))
    def ci(ref):
        col = 0
        for ch in re.match(r'[A-Z]+', ref).group(0):
            col = col * 26 + (ord(ch) - 64)
        return col - 1
    for name, rid in sheets:
        root = ET.fromstring(z.read(relmap[rid].lstrip('/')))
        print('SHEET:', name)
        rows = {}
        for row in root.iter(f'{{{M}}}row'):
            cells = {}
            for c in row.findall(f'{{{M}}}c'):
                ref = c.get('r')
                t = c.get('t')
                f = c.find(f'{{{M}}}f')
                v = c.find(f'{{{M}}}v')
                val = None
                if v is not None:
                    val = v.text
                    if t == 's':
                        val = 'S:' + shared[int(val)]
                    elif t is None and val is not None:
                        try: val = float(val)
                        except ValueError: pass
                elif f is not None:
                    val = 'F:=' + (f.text or '')
                else:
                    isel = c.find(f'{{{M}}}is')
                    if isel is not None:
                        val = 'I:' + ''.join(x.text or '' for x in isel.iter(f'{{{M}}}t'))
                if val is not None:
                    cells[ci(ref)] = (t, val)
            if cells:
                rnum = int(re.search(r'\d+', row.get('r')).group(0))
                rows[rnum] = cells
        for rnum in sorted(rows):
            cs = rows[rnum]
            out = []
            for c in sorted(cs):
                t, val = cs[c]
                s = repr(val)
                if len(s) > 40: s = s[:37] + '...'
                out.append(f"{c}:{t}={s}")
            print(rnum, ' '.join(out))

